-- | rlx for Haskell, over its C ABI (@librlx_capi@): every C function
-- ("RLX.Generated", generated by rlx-bindgen from rlx-bind's tables), on the
-- hand-written "RLX.Support" and "RLX.Manual". Many op names match Prelude's
-- (@sum@, @exp@, …): import this module qualified (@import qualified RLX as R@).
module RLX
  ( module RLX.Generated
  , module RLX.Manual
  , Node
  , none
  , RlxErrorKind (..)
  , RlxError (..)
  , TypedTensor (..)
  ) where

import RLX.Generated
import RLX.Manual
import RLX.Support (Node, RlxError (..), RlxErrorKind (..), TypedTensor (..), none)
